172  otError Message::AppendUriPathOptions(const char *aUriPath)
   173  {
   174      otError     error = OT_ERROR_NONE;
   175      const char *cur   = aUriPath;
   176      const char *end;
   177
   178      while ((end = strchr(cur, '/')) != NULL)
   179      {
   180          SuccessOrExit(error = AppendOption(OT_COAP_OPTION_URI_PATH, static_cast<uint16_t>(end - cur), cur));
   181          cur = end + 1;
   182      }
   183
   184      SuccessOrExit(error = AppendStringOption(OT_COAP_OPTION_URI_PATH, cur));
   185
   186  exit:
   187      return error;
   188  }
